export type TAcceptedMembershipWithOrganization = {
  organizationName: string;
  role: TOrganizationRole;
};

/**
 * Accepted memberships of a user, each with the organization name. Pending memberships (`accepted: false`)
 * are left out because the user has not joined those organizations yet.
 */
export const getAcceptedMembershipsWithOrganizationByUserId = reactCache(
  async (userId: string): Promise<TAcceptedMembershipWithOrganization[]> => {
    validateInputs([userId, ZString]);

    try {
      const memberships = await prisma.membership.findMany({
        where: { userId, accepted: true },
        select: {
          role: true,
          organization: { select: { name: true } },
        },
        orderBy: { organization: { name: "asc" } },
      });

      return memberships.map((membership) => ({
        organizationName: membership.organization.name,
        role: membership.role,
      }));
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) {
        logger.error(error, "Error getting accepted memberships by user id");
        throw new DatabaseError(error.message);
      }

      throw error;
    }
  }
);
